// 码点升序数组 → 二分查找（n=303，最多 8 次比较）
const uint8_t *Font_HZ12_Lookup(uint16_t code)
{
    int lo = 0, hi = HZ12_COUNT - 1;
    while (lo <= hi)
    {
        int mid = (lo + hi) >> 1;
        uint16_t v = font_hz12_codes[mid];
        if (v == code) return font_hz12_bitmaps[mid];
        if (v < code) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
